import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_cute_forward(torch::Tensor x,
                                   torch::Tensor w,
                                   c10::optional<torch::Tensor> b,
                                   int stride, int padding);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T, int Cin, int Kh, int Kw, int OcPerBlock, int Threads, int PVec>
__global__ void conv2d_cute_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int Cout, int H, int Win,
    int stride, int padding,
    int Hout, int Wout)
{
  const int tid = threadIdx.x;

  const int n       = blockIdx.z;
  const int oc_base = blockIdx.y * OcPerBlock;

  const int P_total = Hout * Wout;
  const int PTile   = Threads * PVec;
  const int p_block = blockIdx.x * PTile;

  // Strides
  const int64_t sXn = (int64_t)Cin * H * Win;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;

  const int64_t sYn = (int64_t)Cout * Hout * Wout;
  const int64_t sYc = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;

  // W layout: (Cout, Cin, Kh, Kw)
  const int64_t sWo = (int64_t)Cin * Kh * Kw;
  const int64_t sWc = (int64_t)Kh * Kw;
  const int64_t sWh = (int64_t)Kw;

  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, H, Win),
      make_stride(sXc, sXh, Int<1>{})
  );

  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Hout, Wout),
      make_stride(sYc, sYh, Int<1>{})
  );

  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cout, Cin, Kh, Kw),
      make_stride(sWo, sWc, sWh, Int<1>{})
  );

  // Shared memory for weight tile: OcPerBlock x Cin x Kh x Kw
  constexpr int WTileElems = OcPerBlock * Cin * Kh * Kw;
  __shared__ T sW_raw[WTileElems];
  auto sW = make_tensor(
      make_smem_ptr(sW_raw),
      make_shape(Int<OcPerBlock>{}, Int<Cin>{}, Int<Kh>{}, Int<Kw>{}),
      make_stride(Int<Cin*Kh*Kw>{}, Int<Kh*Kw>{}, Int<Kw>{}, Int<1>{})
  );

  // Load weight tile cooperatively
  for (int idx = tid; idx < WTileElems; idx += Threads) {
    int rem = idx;
    int kw  = rem % Kw; rem /= Kw;
    int kh  = rem % Kh; rem /= Kh;
    int cin = rem % Cin; rem /= Cin;
    int occ = rem;
    int oc  = oc_base + occ;
    T wval = T(0);
    if (oc < Cout) {
      wval = mW(oc, cin, kh, kw);
    }
    sW(occ, cin, kh, kw) = wval;
  }
  __syncthreads();

  // Precompute output positions for this thread
  int p_idx[PVec];
  int oh_arr[PVec];
  int ow_arr[PVec];
  bool valid[PVec];

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_block + tid + i * Threads;
    p_idx[i] = p;
    if (p < P_total) {
      oh_arr[i] = p / Wout;
      ow_arr[i] = p - oh_arr[i] * Wout;
      valid[i] = true;
    } else {
      oh_arr[i] = 0;
      ow_arr[i] = 0;
      valid[i] = false;
    }
  }

  // Accumulators, init with bias
  float acc[OcPerBlock][PVec];
  #pragma unroll
  for (int occ = 0; occ < OcPerBlock; ++occ) {
    int oc = oc_base + occ;
    float bval = 0.0f;
    if (B != nullptr && oc < Cout) {
      bval = (float)B[oc];
    }
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      acc[occ][i] = bval;
    }
  }

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    if (!valid[i]) continue;
    int oh = oh_arr[i];
    int ow = ow_arr[i];

    #pragma unroll
    for (int cin = 0; cin < Cin; ++cin) {
      #pragma unroll
      for (int kh = 0; kh < Kh; ++kh) {
        int ih = oh * stride - padding + kh;
        if ((unsigned)ih >= (unsigned)H) continue;
        #pragma unroll
        for (int kw = 0; kw < Kw; ++kw) {
          int iw = ow * stride - padding + kw;
          if ((unsigned)iw >= (unsigned)Win) continue;

          float xval = (float)mX(cin, ih, iw);

          #pragma unroll
          for (int occ = 0; occ < OcPerBlock; ++occ) {
            float wval = (float)sW(occ, cin, kh, kw);
            acc[occ][i] += xval * wval;
          }
        }
      }
    }
  }

  // Store
  #pragma unroll
  for (int occ = 0; occ < OcPerBlock; ++occ) {
    int oc = oc_base + occ;
    if (oc >= Cout) continue;
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      if (!valid[i]) continue;
      mY(oc, oh_arr[i], ow_arr[i]) = static_cast<T>(acc[occ][i]);
    }
  }
}

torch::Tensor conv2d_cute_forward(torch::Tensor x,
                                   torch::Tensor w,
                                   c10::optional<torch::Tensor> b,
                                   int stride, int padding) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [Cout, Cin, Kh, Kw]");

  int64_t N    = x.size(0);
  int64_t Cin  = x.size(1);
  int64_t H    = x.size(2);
  int64_t Win  = x.size(3);

  int64_t Cout = w.size(0);
  TORCH_CHECK(w.size(1) == Cin, "w.size(1) must equal Cin");
  int64_t Kh = w.size(2);
  int64_t Kw = w.size(3);

  TORCH_CHECK(Cin == 3 && Kh == 11 && Kw == 11, "This kernel is specialized for Cin=3, K=11x11");

  TORCH_CHECK(stride > 0, "stride must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");

  int64_t Hout = (H + 2 * padding - Kh) / stride + 1;
  int64_t Wout = (Win + 2 * padding - Kw) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Hout, Wout}, x.options());

  constexpr int Threads    = 128;
  constexpr int PVec       = 4;
  constexpr int OcPerBlock = 8;

  const int64_t P_total = Hout * Wout;
  const int64_t PTile   = Threads * PVec;

  dim3 block(Threads);
  dim3 grid(
      (unsigned)((P_total + PTile - 1) / PTile),
      (unsigned)((Cout + OcPerBlock - 1) / OcPerBlock),
      (unsigned)N
  );

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  conv2d_cute_kernel<float, 3, 11, 11, OcPerBlock, Threads, PVec><<<grid, block, 0, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cout, (int)H, (int)Win,
      (int)stride, (int)padding,
      (int)Hout, (int)Wout
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_cute_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

conv2d_ext = load_inline(
    name="cute_conv2d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv2d_cute_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include",
                          "/root/cutegen_test/cutegen/cutlass/include/cute/"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        in_channels = 3
        out_channels = 96
        kernel_size = 11
        self.stride = 4
        self.padding = 2

        self.weight = nn.Parameter(torch.empty(out_channels, in_channels, kernel_size, kernel_size))
        self.bias = nn.Parameter(torch.empty(out_channels))

        self.reset_parameters(in_channels, kernel_size)
        self._ext = conv2d_ext

    def reset_parameters(self, in_channels, kernel_size):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        fan_in = in_channels * kernel_size * kernel_size
        bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
        init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv2d_cute_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias,
            self.stride,
            self.padding,
        )

