metadata.cute_to_ptx_src:
import math
import torch
import torch.nn as nn
import torch.nn.init as init

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

# ---------------------------------------------------------------------------
# Hand authored PTX implementing the AlexNet-style conv1:
#   Cin = 3, Kh = Kw = 11, stride/padding given at launch time.
#
# One CUDA thread computes (via a grid-stride loop) a set of output
# elements Y[n, oc, oh, ow].  For every output element it walks the
# (cin, kh, kw) reduction space (flattened into a single 0..362 index,
# since Cin*Kh*Kw == 3*11*11 == 363), applies zero padding by skipping
# out-of-range (ih, iw), accumulates in fp32 starting from the bias
# value, and stores the result.  This mirrors the reduction performed
# by the reference CuTe/CUDA kernel (same input/weight layouts,
# same padding/stride semantics, same fp32 accumulation).
# ---------------------------------------------------------------------------
PTX_SOURCE = r"""
.version 8.3
.target sm_89
.address_size 64

.visible .entry conv2d_kernel(
    .param .u64 conv2d_kernel_param_0,
    .param .u64 conv2d_kernel_param_1,
    .param .u64 conv2d_kernel_param_2,
    .param .u64 conv2d_kernel_param_3,
    .param .u32 conv2d_kernel_param_4,
    .param .u32 conv2d_kernel_param_5,
    .param .u32 conv2d_kernel_param_6,
    .param .u32 conv2d_kernel_param_7,
    .param .u32 conv2d_kernel_param_8,
    .param .u32 conv2d_kernel_param_9,
    .param .u32 conv2d_kernel_param_10,
    .param .u32 conv2d_kernel_param_11
)
{
    .reg .pred %p<8>;
    .reg .b32  %r<48>;
    .reg .b64  %rd<24>;
    .reg .f32  %f<8>;

    ld.param.u64 %rd1, [conv2d_kernel_param_0];   // X
    ld.param.u64 %rd2, [conv2d_kernel_param_1];   // W
    ld.param.u64 %rd3, [conv2d_kernel_param_2];   // B (may be 0 => no bias)
    ld.param.u64 %rd4, [conv2d_kernel_param_3];   // Y
    ld.param.u32 %r1,  [conv2d_kernel_param_4];   // N
    ld.param.u32 %r2,  [conv2d_kernel_param_5];   // Cout
    ld.param.u32 %r3,  [conv2d_kernel_param_6];   // H
    ld.param.u32 %r4,  [conv2d_kernel_param_7];   // Win
    ld.param.u32 %r5,  [conv2d_kernel_param_8];   // stride
    ld.param.u32 %r6,  [conv2d_kernel_param_9];   // padding
    ld.param.u32 %r7,  [conv2d_kernel_param_10];  // Hout
    ld.param.u32 %r8,  [conv2d_kernel_param_11];  // Wout

    cvta.to.global.u64 %rd5, %rd1;   // Xg
    cvta.to.global.u64 %rd6, %rd2;   // Wg
    cvta.to.global.u64 %rd7, %rd4;   // Yg

    setp.eq.s64 %p1, %rd3, 0;        // p1 = (B == 0)

    // total = N * Cout * Hout * Wout
    mul.lo.s32 %r9,  %r7, %r8;       // Hout*Wout
    mul.lo.s32 %r10, %r2, %r9;       // Cout*Hout*Wout
    mul.lo.s32 %r11, %r1, %r10;      // total

    mov.u32 %r12, %ctaid.x;
    mov.u32 %r13, %ntid.x;
    mov.u32 %r14, %tid.x;
    mad.lo.s32 %r15, %r12, %r13, %r14;   // idx
    mov.u32 %r16, %nctaid.x;
    mul.lo.s32 %r17, %r16, %r13;         // stride_total

$LOOP_TOP:
    setp.ge.s32 %p2, %r15, %r11;
    @%p2 bra $DONE;

    // decompose idx -> n, oc, oh, ow  (row-major N,Cout,Hout,Wout)
    div.u32 %r18, %r15, %r8;    // t1 = idx / Wout
    rem.u32 %r19, %r15, %r8;    // ow
    div.u32 %r20, %r18, %r7;    // t2 = t1 / Hout
    rem.u32 %r21, %r18, %r7;    // oh
    div.u32 %r22, %r20, %r2;    // n
    rem.u32 %r23, %r20, %r2;    // oc

    mov.f32 %f1, 0f00000000;

    @%p1 bra $SKIP_BIAS;
    mul.wide.s32 %rd8, %r23, 4;
    cvta.to.global.u64 %rd9, %rd3;
    add.s64 %rd10, %rd9, %rd8;
    ld.global.f32 %f1, [%rd10];
$SKIP_BIAS:

    mov.u32 %r24, 0;      // flattened (cin,kh,kw) index, range [0,363)

$KLOOP_TOP:
    setp.ge.u32 %p3, %r24, 363;
    @%p3 bra $KLOOP_DONE;

    div.u32 %r25, %r24, 121;    // cin = kidx / (Kh*Kw)
    rem.u32 %r26, %r24, 121;    // rem = kidx % (Kh*Kw)
    div.u32 %r27, %r26, 11;     // kh  = rem / Kw
    rem.u32 %r28, %r26, 11;     // kw  = rem % Kw

    mul.lo.s32 %r29, %r21, %r5;   // oh*stride
    sub.s32   %r30, %r29, %r6;    // -padding
    add.s32   %r31, %r30, %r27;   // + kh  => ih (signed)

    setp.ge.u32 %p4, %r31, %r3;   // (unsigned)ih >= H  => out of range
    @%p4 bra $KNEXT;

    mul.lo.s32 %r32, %r19, %r5;   // ow*stride
    sub.s32   %r33, %r32, %r6;
    add.s32   %r34, %r33, %r28;   // iw (signed)

    setp.ge.u32 %p5, %r34, %r4;   // (unsigned)iw >= Win => out of range
    @%p5 bra $KNEXT;

    // X offset = ((n*Cin + cin)*H + ih)*Win + iw
    mad.lo.s32 %r35, %r22, 3, %r25;
    mad.lo.s32 %r36, %r35, %r3, %r31;
    mad.lo.s32 %r37, %r36, %r4, %r34;

    mul.wide.s32 %rd11, %r37, 4;
    add.s64 %rd12, %rd5, %rd11;
    ld.global.f32 %f2, [%rd12];

    // W offset = ((oc*Cin + cin)*Kh + kh)*Kw + kw
    mad.lo.s32 %r38, %r23, 3, %r25;
    mad.lo.s32 %r39, %r38, 11, %r27;
    mad.lo.s32 %r40, %r39, 11, %r28;

    mul.wide.s32 %rd13, %r40, 4;
    add.s64 %rd14, %rd6, %rd13;
    ld.global.f32 %f3, [%rd14];

    fma.rn.f32 %f1, %f2, %f3, %f1;

$KNEXT:
    add.u32 %r24, %r24, 1;
    bra $KLOOP_TOP;

$KLOOP_DONE:
    mul.wide.s32 %rd15, %r15, 4;
    add.s64 %rd16, %rd7, %rd15;
    st.global.f32 [%rd16], %f1;

    add.s32 %r15, %r15, %r17;
    bra $LOOP_TOP;

$DONE:
    ret;
}
"""

_MODULE = None


def _get_module():
    global _MODULE
    if _MODULE is None:
        _MODULE = PtxModule(PTX_SOURCE)
    return _MODULE


def validate_generated_code():
    """Sanity-check that the PTX module compiles and exposes the kernel."""
    module = _get_module()
    fn = module.function("conv2d_kernel")
    assert fn is not None, "conv2d_kernel entry not found in PTX module"
    return True


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        in_channels = 3
        out_channels = 96
        kernel_size = 11
        self.stride = 4
        self.padding = 2
        self.kernel_size = kernel_size
        self.in_channels = in_channels
        self.out_channels = out_channels

        self.weight = nn.Parameter(
            torch.empty(out_channels, in_channels, kernel_size, kernel_size)
        )
        self.bias = nn.Parameter(torch.empty(out_channels))

        self.reset_parameters(in_channels, kernel_size)

    def reset_parameters(self, in_channels, kernel_size):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        fan_in = in_channels * kernel_size * kernel_size
        bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
        init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "input must be a CUDA tensor"

        x = x.contiguous().to(torch.float32)
        w = self.weight.contiguous().to(torch.float32)
        b = self.bias.contiguous().to(torch.float32)

        N, Cin, H, Win = x.shape
        Cout = w.shape[0]
        assert Cin == self.in_channels, "Cin must equal 3"
        assert w.shape[1] == Cin
        assert w.shape[2] == self.kernel_size and w.shape[3] == self.kernel_size

        Hout = (H + 2 * self.padding - self.kernel_size) // self.stride + 1
        Wout = (Win + 2 * self.padding - self.kernel_size) // self.stride + 1
        assert Hout > 0 and Wout > 0

        y = torch.empty((N, Cout, Hout, Wout), device=x.device, dtype=torch.float32)

        total = N * Cout * Hout * Wout
        block_x = 256
        grid_x = (total + block_x - 1) // block_x
        grid_x = max(1, min(grid_x, 65535))

        module = _get_module()
        fn = module.function("conv2d_kernel")

        stream = torch.cuda.current_stream(x.device).cuda_stream

        fn.launch(
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            args=[
                u64(x.data_ptr()),
                u64(w.data_ptr()),
                u64(b.data_ptr()),
                u64(y.data_ptr()),
                i32(N),
                i32(Cout),
                i32(H),
                i32(Win),
                i32(self.stride),
                i32(self.padding),
                i32(Hout),
                i32(Wout),
            ],
            stream=stream,
        )

        return y
